class Solution:
    def search(self, nums: List[int], target: int) -> int:
        """
        修改版二分搜尋
        時間複雜度: O(log n)
        空間複雜度: O(1)
        """
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = (left + right) // 2

            # 找到目標值
            if nums[mid] == target:
                return mid

            # 判斷哪一半是有序的
            # 左半部分有序
            if nums[left] <= nums[mid]:
                # target 在左半部分的範圍內
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1

            # 右半部分有序
            else:
                # target 在右半部分的範圍內
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

        return -1

